<template><section class="space-y-5"><div class="flex items-end justify-between"><h1 class="text-2xl font-bold text-white">{{ $t('portal.notif.title') }}</h1><button class="btn-secondary" @click="markAll">{{ $t('portal.notif.markAll') }}</button></div><div v-for="item in items" :key="item.id" class="pc-card"><p class="text-xs uppercase text-slate-500">{{ item.event_type }}</p><h2 class="mt-1 font-semibold text-white">{{ item.title }}</h2><p class="mt-2 text-sm text-slate-400">{{ item.body }}</p></div><p v-if="error" class="pc-card text-red-300">{{ error }}</p></section></template>
<script setup lang="ts">
definePageMeta({ layout: 'procurement', middleware: ['auth'] }); const { apiFetch } = useApi(); const { listNotifications } = useCommerce(); const items = ref<any[]>([]); const error = ref(''); async function load() { items.value = (await listNotifications()).items } async function markAll() { await apiFetch('/commerce/notifications/read-all', { method: 'POST' }); await load() } onMounted(async () => { try { await load() } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
